    faq: [
      { q: 'क्या मुझे चिंपांज़ी देखने की गारंटी है?', a: 'माहाले में sightings सीज़न में बहुत विश्वसनीय हैं लेकिन कभी गारंटीड नहीं — ये एक बड़े जंगल में जंगली जानवर हैं। ट्रैकर अधिकांश सुबह उनके रात भर के घोंसलों से समुदाय का पता लगाते हैं, और दो ट्रेकिंग दिनों में सफलता दर उत्कृष्ट है। यही कारण है कि हम हर माहाले यात्रा-कार्यक्रम में कम से कम दो ट्रेकिंग दिन शामिल करते हैं।' },
      { q: 'ट्रेकिंग वास्तव में कितनी कठिन है?', a: 'यह दिन-प्रतिदिन बदलती है। शुष्क मौसम में चिंपांज़ी अक्सर ढलानों पर नीचे होते हैं और ट्रेक हर तरफ एक घंटे से कम के हो सकते हैं। जब वे ऊंचे विचरण करते हैं, तो दो से तीन घंटे की खड़ी, उमस भरी पैदल यात्रा की अपेक्षा करें। उचित फिटनेस वाला कोई भी व्यक्ति जो कभी-कभी हाइक करता है वह संभाल लेगा; हमें गतिशीलता संबंधी चिंताओं के बारे में बताएं और हम आसान महीनों के आसपास योजना बना सकते हैं।' },
      { q: 'एक घंटे की सीमा और मास्क नियम क्यों है?', a: 'दोनों चिंपांज़ी की रक्षा करते हैं। चिंपांज़ी मानव श्वसन संक्रमण पकड़ सकते हैं, जो एक जंगली समुदाय के लिए विनाशकारी हो सकता है, और संपर्क समय सीमित करना उनके व्यवहार को स्वाभाविक बनाए रखता है। यह घंटा तेज़ी से गुज़रता है — लेकिन यह वास्तव में एक पूरा घंटा है, नज़दीकी दूरी पर।' },
      { q: 'क्या बच्चे आ सकते हैं?', a: 'माहाले में चिंपांज़ी ट्रेकिंग के लिए न्यूनतम आयु 12 है। छोटे बच्चों वाले परिवार क्लासिक गेम ड्राइव सफारी के लिए बेहतर अनुकूल हैं, जहां कोई न्यूनतम आयु लागू नहीं होती।' },
      { q: 'माहाले कैसे पहुंचें?', a: 'हल्के विमान से — कोई सड़क पहुंच नहीं है। निर्धारित चार्टर अरुशा से उड़ान भरते हैं (एक पड़ाव सहित लगभग 4–5 घंटे), उसके बाद आपके कैंप तक तंगानिका झील में एक खूबसूरत नाव स्थानांतरण। उड़ानें सप्ताह के निश्चित दिनों में चलती हैं, जो यात्रा-कार्यक्रम की अवधि तय करता है।' },
      { q: 'ट्रेकिंग के अलावा और क्या करने के लिए है?', a: 'तंगानिका झील अनुभव का दूसरा आधा हिस्सा है: स्थानिक सिकलिड मछलियों के बीच स्नॉर्कलिंग, कयाकिंग, मछली पकड़ना, धाउ क्रूज़ और बस समुद्रतट पर आराम करना। अधिकांश अतिथि सुबह ट्रेक करते हैं और दोपहर पानी में या उसके किनारे बिताते हैं।' },
      { q: "तंजानिया में चिंपांज़ी ट्रेकिंग की लागत कितनी है?", a: "माहाले यात्रा-कार्यक्रम 3–5 दिनों के लिए लगभग $4,100 प्रति व्यक्ति से शुरू होते हैं, जिसमें वापसी हल्के विमान की उड़ानें, नाव स्थानांतरण, पार्क और ट्रेकिंग शुल्क, भोजन और झील किनारे आवास शामिल हैं। दूरस्थ फ्लाई-इन रसद मुख्य लागत कारक है।" },
    ],
