    faq: [
      { q: 'किस रूट में शिखर तक पहुंचने की सबसे अच्छी संभावना है?', a: 'लंबे रूटों में। 8-दिवसीय लेमोशो (90–95%) और 9-दिवसीय उत्तरी सर्किट (~95%) हमारी सफलता दरों में आगे हैं क्योंकि वे सबसे अधिक अनुकूलन शामिल करते हैं। 6-दिवसीय मारंगु, सबसे सस्ता और सबसे प्रसिद्ध होने के बावजूद, ठीक इसी कारण के उल्टे प्रभाव से 65–70% पर बैठता है।' },
      { q: 'क्या मुझे तकनीकी चढ़ाई का अनुभव चाहिए?', a: "कोई नहीं। किलिमंजारो एक ट्रेक है, तकनीकी चढ़ाई नहीं — मानक रूटों पर कोई रस्सी, हार्नेस या क्रैम्पन नहीं हैं। यदि आप लगातार कई दिनों तक रोज़ छह घंटे ऊपर की ओर चल सकते हैं, तो एकमात्र बचा हुआ चर यह है कि आपका शरीर ऊंचाई को कैसे संभालता है।" },
      { q: 'शिखर रात वास्तव में कैसी होती है?', a: "अधिकांश लोगों के जीवन की सबसे कठिन रात, और वह जिसके बारे में वे हमेशा बात करते हैं। आप लगभग आधी रात को शुरू करते हैं, स्क्री और ठंड में छह से सात घंटे धीरे-धीरे चढ़ते हैं, और सूर्योदय के आसपास क्रेटर किनारे पर पहुंचते हैं। यह ठंडा (अक्सर -10 से -20°C), वायुहीन और मानसिक रूप से कठिन है — और फिर हिमनदों के ऊपर सूरज उगता है और हर कदम सार्थक हो जाता है।" },
      { q: 'यह कितनी ठंडी हो जाती है?', a: 'शिखर रात नियमित रूप से हवा के झोंकों के साथ -10 से -20°C तक पहुंचती है, जबकि पहले दिन का वर्षावन क्षेत्र गर्म और उमस भरा होता है। आप जो भी परत लाएंगे उसका उपयोग करेंगे। एक उचित चार-मौसमी स्लीपिंग बैग और इंसुलेटेड समिट जैकेट अनिवार्य हैं; यदि आप खरीदना नहीं चाहते तो दोनों स्थानीय रूप से किराए पर लिए जा सकते हैं।' },
      { q: 'क्या मैं किलिमंजारो को सफारी के साथ जोड़ सकता हूं?', a: 'यह हमारे सबसे लोकप्रिय संयोजनों में से एक है — अधिकांश पर्वतारोही पर्वत के बाद 4–7 दिन की उत्तरी उद्यान सफारी जोड़ते हैं (आपके पैर वाहन के लिए आभारी होंगे), और कुछ ज़ांज़ीबार पर समाप्त करते हैं। चढ़ाई, सफारी, समुद्रतट: दो हफ्तों में पूरा तंजानिया चाप।' },
      { q: 'मुझे टीम को कितना टिप देना चाहिए?', a: 'किलिमंजारो पर टिपिंग टीम की आय का एक वास्तविक हिस्सा है। एक गाइड के रूप में, समूह के आकार और दिनों के अनुसार समायोजित मानक चढ़ाई में पूरी टीम के लिए प्रति पर्वतारोही लगभग $250–300 का बजट रखें। हम यात्रा से पहले एक स्पष्ट विवरण प्रदान करते हैं ताकि गेट पर कोई अजीब गणना न हो।' },
      { q: "किलिमंजारो चढ़ने में कितना समय लगता है?", a: "रूट पर निर्भर करते हुए पर्वत पर छह से नौ दिन। लंबा सांख्यिकीय रूप से बेहतर है: 8-दिवसीय लेमोशो और 9-दिवसीय उत्तरी सर्किट 90–95% पर्वतारोहियों के लिए सफल होते हैं, जबकि जल्दबाज़ी वाले 6-दिवसीय यात्रा-कार्यक्रम लगभग एक-तिहाई में असफल होते हैं — लगभग हमेशा ऊंचाई के कारण, फिटनेस के कारण नहीं।" },
      { q: "क्या एक शुरुआती व्यक्ति किलिमंजारो चढ़ सकता है?", a: "हां — किलिमंजारो एक ट्रेक है, तकनीकी चढ़ाई नहीं, और दृढ़ निश्चयी नए पर्वतारोही हर दिन शिखर तक पहुंचते हैं। मुख्य बातें हैं अनुकूलन के लिए एक लंबा रूट चुनना, पहले से लंबी पहाड़ी सैर से प्रशिक्षण लेना, और पर्वत पर जानबूझकर धीरे चलना।" },
    ],
