    faq: [
      { q: 'सफारी के लिए न्यूनतम आयु क्या है?', a: 'निजी वाहन में गेम ड्राइव की कोई कानूनी न्यूनतम सीमा नहीं है, और हम खुशी-खुशी लगभग 4–5 वर्ष की उम्र से बच्चों के साथ यात्राओं की योजना बनाते हैं, जब वाह-से-धैर्य अनुपात काम करना शुरू करता है। कुछ लॉज अपनी खुद की न्यूनतम सीमा तय करते हैं (अक्सर 6+, कभी-कभी एक्सक्लूसिव बुकिंग के लिए माफ), और गतिविधि न्यूनतम सीमाएं लागू होती हैं — वॉकिंग सफारी लगभग 16, बैलून उड़ानें आमतौर पर 7+। हम कुछ सुझाने से पहले यह सब आपके वास्तविक बच्चों के अनुसार मैप करते हैं।' },
      { q: 'क्या सफारी बच्चों के लिए सुरक्षित है?', a: 'सही ढंग से चलाई गई, हां। वाहन डिज़ाइन से सुरक्षित हैं, वन्यजीव क्षेत्रों में लॉज मानक रूप से अंधेरे के बाद अतिथियों को साथ ले जाते हैं, और गाइड परिवारों के साथ अनुभवी हैं। व्यावहारिक स्वास्थ्य मद — मलेरिया की रोकथाम, टीकाकरण, धूप और जलयोजन — वही हैं जो वयस्क संभालते हैं, बस छोटे रूप में लागू। दवा की उम्र पर अंतिम शब्द आपके डॉक्टर का है।' },
      { q: 'क्या मेरे बच्चे वास्तव में इसका आनंद लेंगे, या सिर्फ पूल का?', a: 'दोनों, और यही डिज़ाइन है। कोई भी बच्चा आठ घंटे की गेम ड्राइव बर्दाश्त नहीं करता — लेकिन एक गाइड के साथ छोटी ड्राइव जो पहचानने को खेल बना देता है, साथ में पूल का समय, साथ में अलाव-किनारे मार्शमैलो, वह यात्रा बनाती है जिसे बच्चे थीम पार्क से ऊपर रखते हैं। बच्चों को व्यस्त रखने की हमारे गाइडों की क्षमता हमारी फैमिली समीक्षाओं में सबसे अधिक सराही जाने वाली पंक्ति है।' },
      { q: 'फैमिली सफारी कितनी लंबी होनी चाहिए?', a: 'ज़मीन पर छह से आठ दिन संतुलन को हिट करते हैं: बच्चे की गति पर तारांगिरे, क्रेटर और सेरेनगेटी के लिए पर्याप्त, यात्रा के दिनों के साथ स्कूल की छुट्टी के भीतर आने के लिए पर्याप्त छोटा। ज़ांज़ीबार जोड़ने वाले परिवारों के लिए दस दिन खूबसूरती से काम करते हैं — बच्चे समुद्रतट के हिस्से को एक बोनस नहीं, बल्कि सह-मुख्य आकर्षण मानते हैं।' },
      { q: 'क्या दादा-दादी आ सकते हैं?', a: 'बहु-पीढ़ी सफारी हमारे द्वारा बनाई जाने वाली सबसे तेज़ी से बढ़ती यात्राओं में से एक हैं, और यह स्वरूप उनके अनुकूल है: सभी वाहन और नज़ारे साझा करते हैं, जबकि दोपहर में ऊर्जा स्तर बिना अपराधबोध के अलग हो जाते हैं। पूल, आसान रास्ते और फैमिली सुइट वाले लॉज तीन-पीढ़ी समूहों को वास्तव में आरामदायक बनाते हैं।' },
      { q: 'बच्चों के साथ सफारी पहले या ज़ांज़ीबार पहले?', a: 'सफारी पहले। बच्चे यात्रा की शुरुआत में सुबह जल्दी उठना बेहतर संभालते हैं, और समुद्रतट उनके और आपके लिए विसंपीड़न कक्ष का काम करता है। चार सफारी दिन प्लस चार समुद्रतट दिन क्लासिक फैमिली विभाजन है।' },
      { q: "बच्चों को सफारी पर ले जाने की सबसे अच्छी उम्र क्या है?", a: "लगभग 6–8 पर मीठा स्थान खुलता है, जब धैर्य और विस्मय संतुलित होते हैं और अधिकांश लॉज न्यूनतम सीमाएं हट जाती हैं; 10–14 शायद बिल्कुल सही है। हम खुशी-खुशी 4–5 वर्ष की उम्र से एक निजी वाहन के साथ योजना बनाते हैं — गति, उम्र नहीं, वह है जो फैमिली सफारी को बनाती या बिगाड़ती है।" },
    ],
