    faq: [
      { q: 'क्या बैलून सफारी $550 के लायक है?', a: 'अधिकांश यात्रियों के लिए, ईमानदारी से, हां — एक चेतावनी के साथ। यह उपलब्ध सेरेनगेटी का एकमात्र हवाई दृश्य है, शैंपेन ब्रेकफास्ट एक वास्तविक प्रस्तुति है, और यह लगातार अतिथियों की शीर्ष तीन यादों में स्थान पाता है। चेतावनी: एक तंग बजट पर, एक अतिरिक्त गेम-ड्राइव दिन प्रति डॉलर अधिक वन्यजीव देता है। यह अतिरिक्त-खर्च वाला मद है; इसे वैसे ही समझें।' },
      { q: 'क्या हम पलायन के ऊपर उड़ेंगे?', a: 'यदि झुंड एक लॉन्च स्थल की सीमा में हैं, तो पायलट बिल्कुल उनके लिए स्थिति लेते हैं — पलायन के ऊपर तैरना इस स्वरूप का ताज है। लेकिन बैलून जहां हवा जाती है वहां जाते हैं, और झुंड रोज़ चलते हैं; कोई ऑपरेटर इसकी गारंटी नहीं दे सकता। सीज़न में झुंडों के पास एक कैंप बुक करना पासा लोड करने का सबसे अच्छा तरीका है।' },
      { q: 'क्या यह सुरक्षित है? बैलून कौन उड़ाता है?', a: 'उड़ानें नागरिक विमानन विनियमन के तहत लाइसेंस प्राप्त वाणिज्यिक पायलटों द्वारा संचालित होती हैं, सख्त हवा सीमाओं और दैनिक जाओ/न-जाओ निर्णयों के साथ — रद्दीकरण सुरक्षा प्रणाली के काम करने का संकेत है, विफलता का नहीं। लैंडिंग हवा में टकराव-और-खिंचाव हो सकती है; ब्रीफिंग ब्रेस पोज़िशन को कवर करती है, और सपाट जूते आपका योगदान हैं।' },
      { q: 'क्या बच्चे उड़ सकते हैं? कोई अन्य प्रतिबंध?', a: 'ऑपरेटर आमतौर पर लगभग 7 वर्ष की न्यूनतम आयु तय करते हैं और बच्चों को टोकरी के किनारे से देखने के लिए पर्याप्त लंबा होना ज़रूरी है। गर्भवती यात्रियों और हाल की हिप/पीठ/घुटने की सर्जरी वाले यात्रियों को आमतौर पर न उड़ने की सलाह दी जाती है, और टोकरी में प्रवेश व लैंडिंग स्थिति के लिए व्यावहारिक गतिशीलता आवश्यकताएं हो सकती हैं। हम बुकिंग के समय वर्तमान ऑपरेटर नियमों की पुष्टि करते हैं।' },
      { q: 'यदि मौसम उड़ान रद्द कर दे तो क्या होता है?', a: 'पायलट भोर में निर्णय लेता है; यदि नहीं है, तो जहां यात्रा-कार्यक्रम अनुमति देता है वहां अगली उपलब्ध सुबह पर आपको दोबारा बुक किया जाता है, या पूरा रिफंड दिया जाता है। यह अंतिम सुबह की बजाय अपने सेरेनगेटी प्रवास की शुरुआत में बैलून शेड्यूल करने के लिए चुपचाप तर्क भी है।' },
      { q: 'क्या ऐसा करने से मैं गेम ड्राइव खो देता हूं?', a: 'लगभग नहीं। आप एक सुबह की ड्राइव के पहले नब्बे मिनट का व्यापार करते हैं और लगभग 9:30 बजे नाश्ता पहले ही पूरा होने के साथ अपने गाइड से दोबारा मिलते हैं — बाकी दिन सामान्य रूप से आगे बढ़ता है। कई अतिथि कहते हैं कि उड़ान के बाद की ड्राइव एक बोनस राउंड जैसी महसूस होती है।' },
      { q: "सेरेनगेटी बैलून सफारी कितनी देर चलती है?", a: "उड़ान खुद लगभग एक घंटा चलती है, हवा पर निर्भर; पूरा अनुभव आधा दिन है — सुबह लगभग 4:45 बजे भोर-पूर्व पिकअप, फुलाव और ब्रीफिंग, सूर्योदय की उड़ान, शैंपेन बुश ब्रेकफास्ट, और लगभग सुबह 9:30 बजे तक आपके गाइड के पास वापसी।" },
    ],
