    faq: [
      { q: 'क्या यह पर्यटकों के लिए मंचित है, या असली है?', a: 'यही भेद बताता है कि स्वरूप क्यों मायने रखता है। हाद्ज़ाबे सुबह एक असली भोजन-खोज है — आप एक ऐसी गतिविधि में शामिल होते हैं जो वैसे भी हो रही थी, समुदाय की मर्ज़ी से, और परिणाम बदलते रहते हैं क्योंकि वास्तविकता ऐसी ही है। गांव यात्राएं स्वभाव से अधिक संरचित हैं, लेकिन समुदाय-नेतृत्व वाली व्यवस्थाएं, स्थानीय अनुवादक और प्रत्यक्ष भुगतान उन्हें प्रदर्शन की बजाय आदान-प्रदान बनाए रखते हैं। यदि कोई यात्रा कभी नाटक जैसी महसूस हो, तो हमें बताएं; यह वह चीज़ है जिसके विरुद्ध हम सबसे सक्रिय रूप से डिज़ाइन करते हैं।' },
      { q: 'क्या हमारा पैसा वास्तव में समुदायों तक पहुंचता है?', a: 'हां — समुदाय शुल्क सीधे यात्रा पर भुगतान किया जाता है, शिल्प खरीद हाथ-से-हाथ जाती है, और नियुक्त स्थानीय गाइड और अनुवादक उसी क्षेत्र के होते हैं। यही कारण है कि हम बाद में उपहार दुकानों की बजाय यहीं शिल्प खरीदने को प्रोत्साहित करते हैं: मार्जिन का अंतर पूरी तरह निर्माता के हाथ में उतरता है।' },
      { q: 'क्या बच्चों को लाना उचित है?', a: 'बहुत — और ये मुलाकातें अक्सर बच्चों की मुख्य आकर्षण होती हैं। हाद्ज़ाबे बच्चे और आने वाले बच्चे किसी भी वयस्क से ज़्यादा तेज़ी से औपचारिकता घोलते हैं, और धनुष-और-तीर का पाठ एक गारंटीड मुख्य स्मृति है। भोजन-खोज वॉक लगभग 6+ उम्र के बच्चों के अनुकूल है; गांव यात्राएं किसी भी उम्र में काम करती हैं।' },
      { q: 'क्या शिकार होगा, और क्या हमें देखना होगा?', a: 'हाद्ज़ाबे अपनी आजीविका के लिए शिकार करते हैं, जैसा वे हमेशा से करते आए हैं — अधिकांश सुबहों में छोटा शिकार और शहद। क्या शिकार होता है, और सफल होता है, यह सुबह पर निर्भर है। आप अपनी खुद की दूरी और भागीदारी पूरी तरह चुनते हैं; बस साथ चलना और ट्रैकिंग देखना अपने आप में एक पूरा अनुभव है।' },
      { q: 'क्या हम केवल एक वन्यजीव सफारी में एक छोटा सांस्कृतिक पड़ाव जोड़ सकते हैं?', a: 'आसानी से — एक मसाई गांव यात्रा (~$25 प्रति व्यक्ति) या ओल्डुवई गॉर्ज पड़ाव (~$30 प्रति व्यक्ति) किसी भी उत्तरी सर्किट दिन में फिट हो जाता है। हाद्ज़ाबे और डाटोगा के लिए, आयासी झील को एक समर्पित रात चाहिए, जो 4-दिवसीय यात्रा-कार्यक्रम के इर्द-गिर्द बनाई गई है।' },
      { q: 'यह सब किस भाषा में होगा?', a: 'आपका सफारी गाइड स्वाहिली अनुवाद करता है; आयासी में, एक स्थानीय गाइड हाद्ज़ाने — हाद्ज़ाबे की क्लिक भाषा — और डाटोगा के बीच पुल बनाता है। बातचीत इस श्रृंखला के माध्यम से आश्चर्यजनक रूप से अच्छी तरह बहती है, और हर जगह के बच्चे दिखावे की सार्वभौमिक भाषा में धाराप्रवाह संवाद करते हैं।' },
      { q: "एक मसाई गांव यात्रा की लागत कितनी है?", a: "किसी भी सफारी में अतिरिक्त के रूप में, लगभग $25 प्रति व्यक्ति, समुदाय को भुगतान किया गया; एक ओल्डुवई गॉर्ज पड़ाव लगभग $30 है। हाद्ज़ाबे और डाटोगा के साथ पूर्ण आयासी झील विसर्जन हमारी 4-दिवसीय सांस्कृतिक सफारी को $1,250 प्रति व्यक्ति से टिकाता है।" },
    ],
